def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 2:
        return 'C'
    if n == 3:
        if history[2][1] == 'C':
            return 'D'
        else:
            return 'C'

    if history[2][1] == 'C':
        last_my, last_opp = history[-1]
        if last_opp == 'D':
            return 'C'
        return 'D'
    else:
        if n == 99:
            return 'D'
        last_my, last_opp = history[-1]
        opp_def = sum(1 for m, o in history if o == 'D')
        opp_def_rate = opp_def / n
        if opp_def_rate > 0.5:
            return 'D'
        if last_opp == 'D':
            if opp_def_rate < 0.2:
                return 'C'
            if rng.random() < 0.6:
                return 'D'
            return 'C'
        else:
            if opp_def_rate < 0.1 and n > 20 and rng.random() < 0.1:
                return 'D'
            return 'C'
